s=s[:pos]+'''function serializeError(v: Error, superJson: SuperJSON): any {
  const options = superJson.errorStack;
  if (!options) {
    const result: any = { name: v.name, message: v.message };
    if ('cause' in v) result.cause = v.cause;
    superJson.allowedErrorProps.forEach(prop => { result[prop] = (v as any)[prop]; });
    return superJson.errorClassRegistry.getProcessor(v.name)?.(result) ?? result;
  }
  const matches = !options.classFilter.length || options.classFilter.includes(v.name);
  const seen = new Set<Error>();
  function build(error: Error, depth: number, sanitize: boolean): any {
    seen.add(error);
    const ownMatch = !options!.classFilter.length || options!.classFilter.includes(error.name);
    const result: any = { name: error.name, message: sanitize && options!.sanitizeMessage ? sanitizeMessage(error.message) : error.message };
    superJson.allowedErrorProps.forEach(prop => {
      if (prop !== 'stack' && prop !== 'stackFrames' && prop !== 'cause' && prop !== 'errors') result[prop] = (error as any)[prop];
    });
    if (ownMatch && typeof error.stack === 'string') {
      if (options!.mode === 'string' && superJson.allowedErrorProps.includes('stack')) result.stack = processStackString(error.stack, options!);
      if (options!.mode === 'frames' && superJson.allowedErrorProps.includes('stackFrames')) result.stackFrames = processStackFrames(error.stack, options!);
    }
    if (typeof AggregateError !== 'undefined' && error instanceof AggregateError) result.errors = error.errors;
    const cause = error.cause;
    const maxDepth = options!.includeCauses === 'direct' ? 1 : options!.includeCauses === 'deep' ? options!.maxCauseDepth : 0;
    if (depth < maxDepth && cause instanceof Error && !seen.has(cause)) result.cause = build(cause, depth + 1, sanitize);
    return superJson.errorClassRegistry.getProcessor(error.name)?.(result) ?? result;
  }
  return build(v, 0, matches);
}

function deserializeError(v: any, superJson: SuperJSON): Error {
  const cause = v.cause && !(v.cause instanceof Error) && typeof v.cause === 'object' && typeof v.cause.message === 'string'
    ? deserializeError(v.cause, superJson) : v.cause;
  const e = v.name === 'AggregateError' && Array.isArray(v.errors) && typeof AggregateError !== 'undefined'
    ? new AggregateError(v.errors, v.message, { cause }) : new Error(v.message, { cause });
  e.name = v.name;
  e.stack = v.stack;
  superJson.allowedErrorProps.forEach(prop => { (e as any)[prop] = v[prop]; });
  if (Array.isArray(v.stackFrames)) (e as any).stackFrames = v.stackFrames;
  if ('errors' in v) (e as any).errors = v.errors;
  return e;
}

